 "content": "def transform(grid):
    """Mark large uniform rectangular patches as color 4."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    marked = [[False] * w for _ in range(h)]
    # A patch is a uniform rectangle of at least 4 rows by 5 columns.
    for top in range(h):
        same = [True] * w
        for bottom in range(top, h):
            if bottom > top:
                same = [same[c] and grid[bottom][c] == grid[top][c] for c in range(w)]
            if bottom - top + 1 < 4:
                continue
            c = 0
            while c < w:
                if not same[c]:
                    c += 1
                    continue
                color = grid[top][c]
                end = c + 1
                while end < w and same[end] and grid[top][end] == color:
                    end += 1
                if end - c >= 5:
                    for r in range(top, bottom + 1):
                        for col in range(c, end):
                            marked[r][col] = True
                c = end
    for r in range(h):
        for c in range(w):
            if marked[r][c]:
                out[r][c] = 4
    return out
